    20	        try {
    21	            String dateParam = ctx.queryParam("date");
    22	            if (dateParam == null || dateParam.isEmpty()) {
    23	                ctx.status(HttpStatus.BAD_REQUEST);
    24	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Date parameter is required"));
    25	                return;
    26	            }
