    29	            String csv = reportService.generateOccupancyReport(date);
    30	
    31	            ctx.contentType("text/csv; charset=utf-8");
    32	            ctx.result(csv);
    33	        } catch (DateTimeParseException e) {
    34	            ctx.status(HttpStatus.BAD_REQUEST);
    35	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
    36	        }
    37	    }
