    32	    public void createReservation(Context ctx) {
    33	        try {
    34	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
    35	
    36	            LocalDate checkIn = LocalDate.parse(request.checkIn());
    37	            LocalDate checkOut = LocalDate.parse(request.checkOut());
    38	            RatePlan ratePlan = RatePlan.valueOf(request.ratePlan());
    39	
    40	            Reservation reservation = reservationService.createReservation(
    41	                request.roomNumber(),
    42	                request.guestName(),
    43	                request.guestEmail(),
    44	                request.guestCpf(),
    45	                checkIn,
    46	                checkOut,
    47	                request.guests(),
    48	                ratePlan
    49	            );
    50	
    51	            ctx.status(HttpStatus.CREATED);
    52	            ctx.json(ReservationResponse.from(reservation));
    53	
    54	        } catch (DateTimeParseException | IllegalArgumentException e) {
    55	            ctx.status(HttpStatus.BAD_REQUEST);
    56	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid request data"));
    57	        } catch (ReservationService.RoomNotFoundException e) {
    58	            ctx.status(HttpStatus.NOT_FOUND);
    59	            ctx.json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
    60	        } catch (ReservationService.CapacityExceededException e) {
    61	            ctx.status(HttpStatus.UNPROCESSABLE_CONTENT);
    62	            ctx.json(new ErrorResponse("CAPACITY_EXCEEDED", "Guest count exceeds room capacity"));
    63	        } catch (ReservationService.RoomUnavailableException e) {
    64	            ctx.status(HttpStatus.CONFLICT);
    65	            ctx.json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
    66	        } catch (ReservationService.InvalidRequestException e) {
    67	            ctx.status(HttpStatus.BAD_REQUEST);
    68	            ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
    69	        }
    70	    }
    71	
    72	    public void getReservation(Context ctx) {
    73	        try {
    74	            long id = Long.parseLong(ctx.pathParam("id"));
    75	            Reservation reservation = reservationService.getReservation(id);
    76	            ctx.json(ReservationResponse.from(reservation));
    77	        } catch (NumberFormatException e) {
    78	            ctx.status(HttpStatus.BAD_REQUEST);
    79	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
