   159	
   160	            if (reservation.getAmountPaid().signum() == 0) {
   161	                ctx.status(HttpStatus.CONFLICT);
   162	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Document is only available for paid reservations"));
   163	                return;
   164	            }
   165	
   166	            DocumentResponse document = createDocumentResponse(reservation);
   167	            ctx.json(document);
   168	        } catch (NumberFormatException e) {
   169	            ctx.status(HttpStatus.BAD_REQUEST);
   170	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
