   177	    private DocumentResponse createDocumentResponse(Reservation reservation) {
   178	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
   179	
   180	        return new DocumentResponse(
   181	            "Comprovante de reserva",
   182	            reservation.getId(),
   183	            reservation.getGuestName(),
   184	            reservation.getGuestCpf(),
   185	            reservation.getRoomNumber(),
   186	            room.getType().name(),
   187	            reservation.getCheckIn(),
   188	            reservation.getCheckOut(),
   189	            reservation.getNights(),
   190	            reservation.getSubtotal(),
   191	            reservation.getDiscount(),
   192	            reservation.getTotal()
   193	        );
   194	    }
   195	}
