    10	public final class DocumentService {
    11	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    12	    private static final NumberFormat CURRENCY_FORMAT = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
    13	
    14	    public String generateReceipt(Reservation reservation, String roomType) {
    15	        StringBuilder receipt = new StringBuilder();
    16	
    17	        receipt.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
    18	        receipt.append("Hóspede: ").append(reservation.getGuestName())
    19	               .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
    20	        receipt.append("Quarto: ").append(reservation.getRoomNumber())
    21	               .append(" (").append(roomType).append(")\n");
    22	        receipt.append("Entrada: ").append(reservation.getCheckIn().format(DATE_FORMATTER))
    23	               .append(" | Saída: ").append(reservation.getCheckOut().format(DATE_FORMATTER))
    24	               .append(" | ").append(reservation.getNights())
    25	               .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
    26	        receipt.append("Diárias: ").append(formatCurrency(reservation.getSubtotal())).append("\n");
    27	
    28	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    29	            receipt.append("Desconto: ").append(formatCurrency(reservation.getDiscount())).append("\n");
    30	        }
    31	
    32	        receipt.append("Total: ").append(formatCurrency(reservation.getTotal()));
    33	
    34	        return receipt.toString();
    35	    }
    36	
    37	    public String generateConfirmationEmail(Reservation reservation, String roomType) {
    38	        String receipt = generateReceipt(reservation, roomType);
    39	
    40	        StringBuilder email = new StringBuilder();
    41	        email.append("Olá, ").append(reservation.getGuestName()).append("!\n\n");
    42	        email.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
    43	        email.append(receipt).append("\n\n");
    44	        email.append("A entrada é a partir das 14h, e a saída, até as 12h.\n");
    45	        email.append("Até breve!");
    46	
    47	        return email.toString();
    48	    }
    49	
    50	    private String formatCpf(String cpf) {
    51	        if (cpf.length() == 11) {
    52	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
    53	                   cpf.substring(6, 9) + "-" + cpf.substring(9, 11);
    54	        }
    55	        return cpf;
    56	    }
    57	
    58	    private String formatCurrency(BigDecimal amount) {
    59	        return CURRENCY_FORMAT.format(amount);
    60	    }
    61	}
