    24	    public String generateOccupancyReport(LocalDate date) {
    25	        List<Reservation> reservations = reservationRepository.findByNightAndPaid(date);
    26	        List<Room> allRooms = roomRepository.findAll();
    27	
    28	        StringBuilder csv = new StringBuilder();
    29	        csv.append("room,type,reservation,check_in,check_out\n");
    30	
    31	        for (Reservation reservation : reservations) {
    32	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
    33	            csv.append(reservation.getRoomNumber()).append(",");
    34	            csv.append(room.getType().name()).append(",");
    35	            csv.append(reservation.getId()).append(",");
    36	            csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
    37	            csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append("\n");
    38	        }
    39	
    40	        csv.append("total,").append(reservations.size()).append("/").append(allRooms.size());
    41	
    42	        return csv.toString();
    43	    }
    44	
    45	    public String generateRevenueReport(int year, int month) {
    46	        List<Reservation> reservations = reservationRepository.findByMonth(year, month);
    47	
    48	        StringBuilder csv = new StringBuilder();
    49	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    50	
    51	        BigDecimal total = BigDecimal.ZERO;
    52	
    53	        for (Reservation reservation : reservations) {
    54	            BigDecimal revenue = reservation.getAmountPaid();
    55	            if (reservation.getRefund() != null) {
    56	                revenue = revenue.subtract(reservation.getRefund());
    57	            }
    58	
    59	            csv.append(reservation.getId()).append(",");
    60	            csv.append(reservation.getRoomNumber()).append(",");
    61	            csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
    62	            csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append(",");
    63	            csv.append(reservation.getStatus().name()).append(",");
    64	            csv.append(formatDecimal(revenue)).append("\n");
    65	
    66	            total = total.add(revenue);
    67	        }
    68	
    69	        csv.append("total,").append(formatDecimal(total));
    70	
    71	        return csv.toString();
    72	    }
    73	
    74	    private String formatDecimal(BigDecimal value) {
    75	        return value.stripTrailingZeros().toPlainString();
    76	    }
    77	}
