     6	public final class EmailValidationRule implements MessageRule {
     7	    @Override
     8	    public boolean apply(OutgoingMessage message) {
     9	        if (!isValidEmail(message.getTo())) {
    10	            message.block();
    11	            return false;
    12	        }
    13	        return true;
    14	    }
    15	
    16	    private boolean isValidEmail(String email) {
    17	        if (email == null || email.isEmpty()) {
    18	            return false;
    19	        }
    20	
    21	        int atCount = 0;
    22	        int atPosition = -1;
    23	
    24	        for (int i = 0; i < email.length(); i++) {
    25	            if (email.charAt(i) == '@') {
    26	                atCount++;
    27	                atPosition = i;
    28	            }
    29	        }
    30	
    31	        if (atCount != 1) {
    32	            return false;
    33	        }
    34	
    35	        if (atPosition == 0 || atPosition == email.length() - 1) {
    36	            return false;
    37	        }
    38	
    39	        String afterAt = email.substring(atPosition + 1);
    40	        int dotCount = 0;
    41	        for (char c : afterAt.toCharArray()) {
    42	            if (c == '.') {
    43	                dotCount++;
    44	            }
    45	        }
    46	
    47	        return dotCount >= 1;
    48	    }
    49	}
