   127	    public List<Reservation> findConflicting(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
   128	        String sql = """
   129	            SELECT * FROM reservations
   130	            WHERE room_number = ?
   131	              AND status != 'CANCELLED'
   132	              AND check_in < ?
   133	              AND check_out > ?
   134	            """;
   135	
   136	        List<Reservation> reservations = new ArrayList<>();
   137	
   138	        try (Connection conn = dbManager.getConnection();
