     1	package com.pousadamarealta.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	
     8	public final class PriceCalculator {
     9	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    10	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
    11	
    12	    public static boolean isHighSeason(LocalDate date) {
    13	        Month month = date.getMonth();
    14	        int day = date.getDayOfMonth();
    15	
    16	        if (month == Month.DECEMBER && day >= 15) {
    17	            return true;
    18	        }
    19	
    20	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    21	            return true;
    22	        }
    23	
    24	        if (month == Month.JULY) {
    25	            return true;
    26	        }
    27	
    28	        return false;
    29	    }
    30	
    31	    public static BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate night) {
    32	        BigDecimal price = baseRate;
    33	        if (isHighSeason(night)) {
    34	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
    35	        }
    36	        return price.setScale(2, ROUNDING_MODE);
    37	    }
    38	
    39	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    40	        BigDecimal subtotal = BigDecimal.ZERO;
    41	        LocalDate current = checkIn;
    42	
    43	        while (current.isBefore(checkOut)) {
    44	            BigDecimal nightPrice = calculateNightPrice(baseRate, current);
    45	            subtotal = subtotal.add(nightPrice);
    46	            current = current.plusDays(1);
    47	        }
    48	
    49	        return subtotal.setScale(2, ROUNDING_MODE);
    50	    }
    51	
    52	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    53	        BigDecimal discount = subtotal.multiply(ratePlan.getDiscountRate());
    54	        return discount.setScale(2, ROUNDING_MODE);
    55	    }
    56	
    57	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    58	        return subtotal.subtract(discount).setScale(2, ROUNDING_MODE);
    59	    }
    60	}
